import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { analyzeChan } from './index.js';
import { analyzeExternalChan } from './external/index.js';
import { analyze } from './external/upstream.js';

const fixture = JSON.parse(readFileSync(new URL('./fixtures/600851-qfq-2026-10-27.json', import.meta.url)));
// Independent snapshot generated by the original CommonJS upstream code.
const baseline = JSON.parse(readFileSync(new URL('./fixtures/600851-external-upstream-274f7a2.json', import.meta.url)));

test('the separately retained upstream engine still matches its original snapshot', () => {
  const bars = fixture.map(r => ({ t: Date.parse(`${r.date}T00:00:00Z`), o: r.open, h: r.high, l: r.low, c: r.close, v: r.volume }));
  const result = analyze(bars, { period: 'day', limit: bars.length });
  const { fractals, bis, segments, pivots, signals, beichi, trend } = result;
  assert.deepEqual({ fractals, bis, segments, pivots, signals, beichi, trend }, baseline);
  assert.deepEqual([bis.length, segments.length, pivots.length], [51, 9, 13]);
});

for (const sign of [1, -1]) {
  test(`combined engine uses one production pen chain for segments and reference centers (sign ${sign})`, () => {
    const rows = fixture.map(r => ({ ...r, open: sign * r.open, close: sign * r.close,
      high: sign === 1 ? r.high : -r.low, low: sign === 1 ? r.low : -r.high }));
    const result = analyzeExternalChan(rows, '101');
    const original = analyzeChan(rows, '101');
    assert.equal(result.definition.engine, 'external');
    assert.deepEqual(result.bi, original.bi);
    assert.deepEqual(result.biLine, original.biLine);
    assert.deepEqual(result.segments, original.segments);
    assert.deepEqual(result.pendingSegments, original.pendingSegments);
    assert.deepEqual(result.fractalDetails, original.fractalDetails);
    assert.equal(result.upstream, null, 'unrelated upstream signals and trend are not attached to this chart');
    assert.equal(result.outlook.ok, false);
    assert.deepEqual(result.trades, []);

    for (let i = 0; i < result.segments.length; i++) {
      const s = result.segments[i];
      assert.ok(s.confirmed && s.stroke_count >= 3 && s.stroke_count % 2 === 1);
      assert.ok(s.direction === 'up' ? s.end.price > s.start.price : s.end.price < s.start.price);
      assert.ok(result.bi.some(p => p.time === s.start.time && p.price === s.start.price));
      assert.ok(result.bi.some(p => p.time === s.end.time && p.price === s.end.price));
      if (i) {
        const prev = result.segments[i - 1];
        assert.deepEqual([prev.end.time, prev.end.price], [s.start.time, s.start.price]);
        assert.notEqual(prev.direction, s.direction);
      }
    }
    for (const zone of result.zs) {
      const start = result.bi.findIndex(p => p.time === zone.sdt);
      assert.ok(start >= 0);
      const endpoints = result.bi.slice(start, start + 4);
      assert.equal(endpoints.length, 4);
      assert.ok(endpoints.slice(0, 3).every(p => p.confirmed));
      const intervals = endpoints.slice(0, 3).map((p, i) => [Math.min(p.price, endpoints[i + 1].price), Math.max(p.price, endpoints[i + 1].price)]);
      assert.equal(zone.zd, Math.max(...intervals.map(p => p[0])));
      assert.equal(zone.zg, Math.min(...intervals.map(p => p[1])));
      assert.ok(zone.zg > zone.zd);
      assert.equal(zone.level, 'pen_reference');
      assert.equal(zone.evidence.formation.kind, 'three_completed_pens');
      assert.equal(zone.evidence.formation.pens.length, 3);
      assert.ok(zone.confirmed_time >= zone.evidence.formation.pens[2].end.time);
      if (zone.closed_time != null) assert.ok(zone.closed_time >= zone.confirmed_time);
    }
    if (sign === 1) {
      assert.equal(result.zs.length, 3);
      const latest = result.zs.at(-1);
      assert.deepEqual([latest.zd, latest.zg], [7.55, 8.91]);
      assert.deepEqual([rows[latest.sdt - 1].date, rows[latest.edt - 1].date,
        rows[latest.confirmed_time - 1].date, latest.status, latest.phase],
      ['2025-12-31', '2026-09-21', '2026-03-13', 'active', 'leaving']);
      assert.equal(result.bi.some((p, i) => rows[p.time - 1].date === '2025-03-24'
        && rows[result.bi[i + 1]?.time - 1]?.date === '2025-06-09'), false,
      'the historical invalid pen spanning a more extreme processed bottom is absent');
    } else {
      assert.equal(result.inputProblem, undefined, 'valid negative adjusted prices remain valid input');
      assert.ok(result.zs.length > 0);
    }
  });
}

test('malformed input stops the combined structure instead of joining across a missing candle', () => {
  const rows = fixture.slice(0, 30).map(r => ({ ...r }));
  rows[10].high = NaN;
  const result = analyzeExternalChan(rows);
  assert.equal(result.inputProblem.reason, 'invalid_candle');
  assert.equal(result.inputProblem.index, 10);
  assert.deepEqual(result.zs, []);
  assert.deepEqual(result.segments, []);
});

test('short history is not cut off by the upstream full-engine 20-bar minimum', () => {
  const rows = fixture.slice(0, 19);
  const result = analyzeExternalChan(rows);
  const local = analyzeChan(rows);
  assert.deepEqual(result.bi, local.bi);
  assert.equal(result.insufficientData, undefined);
});
